//! Programs compiled by the pinned FTEQCC (fte-team/fteqw@f937b9d88f71fc4429db5fe56c6a98d922711b2e)
//! and its diagnostics for each, which the FTEQCC profile reports alike (2026-10-28).

use std::path::PathBuf;

use qc_preproc::CommandLine;
use qc_syntax::Dialect;

use crate::db::Db;
use crate::expand::ModuleInput;
use crate::symbol::FileId;

/// Every diagnostic message of the FTEQCC file `source`, in order.
fn messages(source: &str) -> Vec<String> {
    let mut db = Db::new();
    db.set_dialect(Dialect::Fteqcc);
    db.set_file(
        FileId(0),
        PathBuf::from("t.qc"),
        format!("{source}\n").into_bytes(),
    );
    let analysis = db.analyze_module(&ModuleInput {
        compiled: vec![FileId(0)],
        command_line: CommandLine::new::<&str>(&[]),
        ..ModuleInput::default()
    });
    analysis
        .diagnostics()
        .map(|d| d.diagnostic.message.clone())
        .collect()
}

/// Each case's program: its prelude, by its index in [`PRELUDES`], and its last line.
fn check(cases: &[(usize, &str, &[&str])]) {
    for &(prelude, last, expected) in cases {
        let source = format!("{}\n{last}", PRELUDES[prelude]);
        assert_eq!(messages(&source), expected, "{source}");
    }
}

// spec FTEF-34.1: a statement is checked as `QCC_PR_ParseStatement` checks it
// spec FTEF-34.3: a switch's cases are checked against its operand
// spec FTEF-30.2: a condition is tested as `QCC_Generate_OP_IFNOT` tests it
#[test]
fn statements_1_are_reported_as_fteqcc_reports_them() {
    check(&STATEMENTS[0..250]);
}

